function liqLimpio(text) {
  return String(text == null ? "" : text)
    .replace(/\u00a0/g, " ")
    .replace(/\d{1,2}[/.-]\d{1,2}[/.-]\d{2,4}/g, " ")
    .replace(/\d{1,2}\/\d{1,2}/g, " ");
}

/** El texto sin fechas y sin porcentajes: solo quedan importes y cantidades. */
